"""선언적 Base. 제약 이름 규칙을 고정해 마이그레이션·오류 메시지에서 제약을 식별하게 한다."""

from sqlalchemy import Identity, MetaData
from sqlalchemy.orm import DeclarativeBase

from app.domain.common.ids import MAX_ID

NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


def identity_key() -> Identity:
    """`GENERATED BY DEFAULT AS IDENTITY (MAXVALUE 2^53-1)`.

    앱이 미리 받은 id도, DB 기본값으로 매겨지는 id도 같은 시퀀스를 쓴다.
    """
    return Identity(always=False, start=1, increment=1, maxvalue=MAX_ID)


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)
